import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './app/store';
import { ThemeProvider } from './context/ThemeContext';
import AlertState from './context/alert/AlertState';
import { NewsProvider } from './context/NewsContext';
import { CommunityProvider } from './context/CommunityContext';
import { WebSocketProvider } from './context/WebSocketContext';
import { AuthProvider } from './context/AuthContext';
import App from './App';
import './index.css';

// Initialize auth state from localStorage if token exists
const initializeAuth = () => {
  const token = localStorage.getItem('token');
  if (token) {
    // You might want to validate the token with the server here
    // For now, we'll just set the user as authenticated
    store.dispatch({ 
      type: 'auth/loginSuccess', 
      payload: JSON.parse(localStorage.getItem('user') || '{}') 
    });
  }
};

// Initialize authentication
initializeAuth();

const root = createRoot(document.getElementById('root'));

// Create a component that wraps the app with all providers
const AppWithProviders = () => (
  <React.StrictMode>
    <Provider store={store}>
      <BrowserRouter
        future={{
          v7_startTransition: true,
          v7_relativeSplatPath: true
        }}
      >
        <ThemeProvider>
          <AlertState>
            <AuthProvider>
              <NewsProvider>
                <CommunityProvider>
                  <WebSocketProvider>
                    <App />
                  </WebSocketProvider>
                </CommunityProvider>
              </NewsProvider>
            </AuthProvider>
          </AlertState>
        </ThemeProvider>
      </BrowserRouter>
    </Provider>
  </React.StrictMode>
);

root.render(<AppWithProviders />);
